  s=copy.deepcopy(maps[p]);s.update(disposition='excluded' if p in EX else 'examinable',exclusionReason=EX.get(p),conceptIds=[c['id'] for c in concepts if s['id'] in c['slideIds']],lectureId='L51',week=11,lectureTitle='Introducing the Hardware for the Robot',printedLectureNumber=51,printedSlideNumber=None if p==1598 else str(p-1594),printedSlideNumberStatus='absent' if p==1598 else 'present',printedNumberEvidence='Actual rendered footer inspected separately; physical page 1598 has no visible footer number.')
